(892, 1239, 'analisa', '[{\"langkah\":\"Pengawas melakukan inspeksi area\",\"bahaya\":[{\"risiko\":\"Pengawas tersandung diarea kerja\",\"pengendalian\":[\"screening area untuk dilakukan pekerjaan\",\"Mapping area untuk dilakukan pekerjaan\"]}]},{\"langkah\":\"Travel PC 200  Long Arm Melewati Area Kabel\",\"bahaya\":[{\"risiko\":\"Boom PC 200 Long Arm menyentuh\\/kabel nyangkut\",\"pengendalian\":[\"Jaga Jarak aman Min 3M antar kabel dan posisikan Boom dan Arm PC ke bawah\",\"Kecepatan unit travel Max 5 KM\\/JAM\",\"Wajib 2 spotter sisi depan dan belakang\",\"Komunikasi aktif 2 arah\"]}]},{\"langkah\":\"Pengangkatan dan Penjajaran Pipa HDPE\",\"bahaya\":[{\"risiko\":\"Pipa HDPE menghantam unit\",\"pengendalian\":[\"Angkat pipa perlahan dengan menggunakan sling belt\\/sling wire\",\"Posisi pangangkatan dan penjajaran pipa HDPE lurus tanpa ada lengkungan tiap sambungan\"]},{\"risiko\":\"PC 200 Long Arm menghantam pekerja\",\"pengendalian\":[\"Pekerja tidak berada diradius swing PC 200 Long Arm\",\"PC 200 Long Arm tidak melakukan pergerakan secara tiba-tiba\",\"Aktif komunikasi 2 arah antar pekerja dengan operator\"]}]},{\"langkah\":\"Menyiapkan tool dan mesin peralatan dengan manual handling\",\"bahaya\":[{\"risiko\":\"Cidera tulang punggung\",\"pengendalian\":[\"Angkat beban lebih dari 1 orang\",\"Gunakan metode pengangkatan yang benar\"]},{\"risiko\":\"Jari tangan terjepit tool\",\"pengendalian\":[\"Angkat tool dan peralatan pada handle frame lebih dari 1 orang\"]},{\"risiko\":\"Jari tangan tertusuk serabut sling wire\",\"pengendalian\":[\"Pegang sling wire pada fitting sling\\/hook\",\"Jangan gunakan sling yang sudah berserabut\"]}]},{\"langkah\":\"Memposisikan mesin welding dan rangkaian kabel\",\"bahaya\":[{\"risiko\":\"Cidera tulang punggung\",\"pengendalian\":[\"Angkat beban lebih dari 1 orang\",\"Gunakan metode pengangkatan yang benar\"]},{\"risiko\":\"Jari tangan terjepit frame mesin\",\"pengendalian\":[\"Angkat mesin welding pada handle frame\"]},{\"risiko\":\"Mesin welding gagal beroperasi\",\"pengendalian\":[\"P2H mesin welding dengan benar\",\"Laporkan ccr jika ditemukan kerusakan atau kelainan pada mesin\"]},{\"risiko\":\"Pekerja tersengat aliran listrik\",\"pengendalian\":[\"Tempatkan kabel-kabel dan peralatan sesuai dengan kebutuhan sebelum listrik dihubungkan\",\"Kondisi area tidak basah, tidak terdapat potensi tumpahan air pada colokan listrik\",\"Tempatkan colokan listrik pada area aman yang tidak mengganggu lintasan pekerja\"]}]},{\"langkah\":\"Groundtest mesin welding tanpa beban\",\"bahaya\":[{\"risiko\":\"Mesin welding gagal beroperasi\",\"pengendalian\":[\"Laporkan ccr jika ditemukan kerusakan atau kelainan pada mesin\"]},{\"risiko\":\"Jari tangan pekerja terjepit HYDROULIC FRAME\",\"pengendalian\":[\"Tidak ada pekerja yang menyentuh hydrolic saat groundtest\",\"Komunikasi 2 arah antar pekerja\"]}]},{\"langkah\":\"PC 200 Long Arm menyiapkan HDPE untuk di angkat ke frame hydrolik\",\"bahaya\":[{\"risiko\":\"Pekerja terbentur PC 200 Long Arm\",\"pengendalian\":[\"Tidak ada pekerja yang berada diradius swing PC 200 Long Arm\",\"Aktif komunikasi 2 arah antar pekerja dan operator\"]},{\"risiko\":\"Pipa HDPE tertusuk\\/tersayat kuku baket\",\"pengendalian\":[\"Geser perlahan pipa HDPE dengan punggung kuku dan punggung baket\",\"Komunikasi aktif 2 arah dengan pengawas\"]}]},{\"langkah\":\"Pekerja memasang slingbelt pada pipa HDPE\",\"bahaya\":[{\"risiko\":\"Pekerja terbentur PC 200 Long Arm\",\"pengendalian\":[\"Pasang belt ketika PC 200 Long Arm sudah berhenti bergerak dan memberi aba-aba\",\"Komunikasi 2 arah antar operator dengan pekerja\"]},{\"risiko\":\"Jari tangan pekerja terjepit pipa HDPE\",\"pengendalian\":[\"pasang belting pada celah pipa HDPE yang sudah tersedia\"]}]},{\"langkah\":\"PC 200 Long Arm mengangkat dan memposisikan pipa HDPE pada frame hydrolic depan\",\"bahaya\":[{\"risiko\":\"Pekerja terbentur pipa HDPE\",\"pengendalian\":[\"Pekerja tidak berada di radius swing sampai PC 200 Long Arm benar-benar berhenti gerak\",\"Angkat pipa HDPE perlahan sampai posisi di atas frame\"]}]},{\"langkah\":\"PC 200 Long Arm meletakan pipa HDPE pada frame hyd depan dengan spotter\",\"bahaya\":[{\"risiko\":\"Spotter terbentur pipa HDPE\",\"pengendalian\":[\"PC 200 Long Arm tidak melakukan gerakan secara tiba-tiba\",\"PC 200 Long Arm mengikuti arahan spotter dengan gerakan perlahan\"]}]},{\"langkah\":\"Pekerja mengatur jarak permukaan antar pipa HDPE menggunakan hydrolik\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja terjepit frame hydrolic\",\"pengendalian\":[\"Tidak meletakan jari tangan pada frame hydrolic saat hydrolic bergerak\",\"Aktif komunikasi 2 arah sesama pekerja\"]}]},{\"langkah\":\"Pekerja memasang clamp frame\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja terjepit clamp\",\"pengendalian\":[\"Pegang pangkal kunci dan putar perlahan\"]}]},{\"langkah\":\"Pekerja memasang mesin serut perata pipa HDPE ke frame\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja terjepit mesin serut pipa HDPE\",\"pengendalian\":[\"Pasang perlahan mesin serut dengan lebih dari 1 orang\",\"Angkat mesin serut pada handle nya\"]},{\"risiko\":\"Jari tangan pekerja tersayat mesin serut\",\"pengendalian\":[\"Kabel penghubung tidak terpasang saat memasang mesin serut\"]}]},{\"langkah\":\"Pekerja melakukan perataan pipa HDPE dengan mesin serut\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja terpotong mesin serut\",\"pengendalian\":[\"Tidak ada pekerja yang menyentuh mesin serut ketika beroperasi\",\"Komunikasi 2 arah antar pekerja\"]},{\"risiko\":\"Mesin serut overload\",\"pengendalian\":[\"Beri tekanan pada mesin serut kurang dari 2 bar atau tebal sayatan tidaklebih dari 2mm\"]}]},{\"langkah\":\"Melepas mesin serut perata pipa HDPE dari frame\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja tersayat mesin serut\",\"pengendalian\":[\"Kabel penghubung tidak terpasang saat melepas mesin serut\"]},{\"risiko\":\"Jari tangan pekerja terjepit mesin serut\",\"pengendalian\":[\"Angkat mesin serut pada handle dan pangkal mesin\"]}]},{\"langkah\":\"Membersihkan permukaan pipa HDPE dengan lap basah\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerjatersayat sudut pipa HDPE\",\"pengendalian\":[\"Lap permukaan pipa perlahan, tidak terburu-buru\"]}]},{\"langkah\":\"Memasang pemanas (plate heating) pada mesin welding\",\"bahaya\":[{\"risiko\":\"Anggota tubuh pekerja terpapar\\/tersentuh plat panas\",\"pengendalian\":[\"Angkat dan letakan pemanas perlahan pada mesin welidng\",\"Angkat dengan memberi jarak anggota tubuh dari plat panas\"]}]},{\"langkah\":\"Memanaskan pipa HDPE\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja terjepit frame hydrolic\",\"pengendalian\":[\"Tidak meletakan jari tangan pada frame hydrolic saat hydrolic bergerak\",\"Aktif komunikasi 2 arah sesama pekerja\"]},{\"risiko\":\"Pipa HDPE meleleh tidak terukur\",\"pengendalian\":[\"Panaskan pipa pada temperatur Min 210\'C\"]},{\"risiko\":\"Preasure pipa HDPE overload\",\"pengendalian\":[\"Beri tekanan pada pemanas hanya 1x ( satu kali ) dan maximal 4 BAR\",\"Biarkan preasure menurun hingga 1 bar atau besar lelehan pipa HDPE 6mm\"]}]},{\"langkah\":\"Melepas pemanas (plate heating) pada mesin welding\",\"bahaya\":[{\"risiko\":\"Anggota tubuh pekerja terpapar\\/tersentuh plat panas\",\"pengendalian\":[\"Angkat dan letakan pemanas perlahan kembali ke dudukannya\",\"Angkat dengan memberi jarak anggota tubuh dari plat panas\"]}]},{\"langkah\":\"Menghubungkan kedua pipa HDPE dengan hydrolic preasure\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja terjepit frame hydrolic\",\"pengendalian\":[\"Tidak meletakan jari tangan pada frame hydrolic saat hydrolic bergerak\",\"Aktif komunikasi 2 arah sesama pekerja\"]},{\"risiko\":\"Pipa HDPE tidak terhubung sempurna\",\"pengendalian\":[\"Beri tekanan preasure pada hydrolic untuk menghubungkan pipa HDPE lebih besar dari 5 BAR\"]}]},{\"langkah\":\"Pendinginan pipa HDPE\",\"bahaya\":[{\"risiko\":\"Pipa HDPE terlepas pada sambungan akibat gerakan hydolic\",\"pengendalian\":[\"Matikan power mesin welding selama pendinginan\"]}]},{\"langkah\":\"Melepas clamp frame\",\"bahaya\":[{\"risiko\":\"Jari tangan pekerja terjepit clamp frame dan kunci\",\"pengendalian\":[\"Pegang pangkal kunci dan putar baut perlahan\"]}]},{\"langkah\":\"Menurunkan pipa HDPE dari frame dengan PC 200 Long Arm\",\"bahaya\":[{\"risiko\":\"Pekerja terhantam pipa HDPE\\/bucket PC 200 Long Arm\",\"pengendalian\":[\"PC 200 Long Arm tidak melakukan pergerakan secara tiba-tiba, bergerak secara perlahan\",\"Spotter mengarahkan pergerakan pipa dan PC 200 Long Arm\",\"Aktif komunikasi 2 arah antar pekerja denganoperator PC 200 Long Arm\"]}]},{\"langkah\":\"Pekerja memasang sling wire pada ujung pipa HDPE\",\"bahaya\":[{\"risiko\":\"Jari pekerja tertusuk serabut sling\",\"pengendalian\":[\"Pegang sling pada fitting sling atau hook\",\"Tidak menggunakan sling yang sudah berserabut\"]}]},{\"langkah\":\"PC 200 Long Arm menarik pipa HDPE dengan sling wire\",\"bahaya\":[{\"risiko\":\"Pipa HDPE menghantam framae mesin welding\",\"pengendalian\":[\"Spotter mengarahkan jalur tarik pipa HDPE\"]},{\"risiko\":\"PC 200 Long Arm menabrak jalur lintasan kabel gantung\",\"pengendalian\":[\"Spotter mengarahkan posisi PC 200 Long Arm dan menghindari jalur lintasan kabel\",\"Aktif komunikasi 2 arah antar operator PC 200 Long Arm dengan spotter dan pekerja\"]}]},{\"langkah\":\"Housekeeping area kerja\",\"bahaya\":[{\"risiko\":\"Pekerja tersandung dan tergelincir\",\"pengendalian\":[\"Rapikan sisa potongan pipa HDPE\",\"Gulung kabel mesin welding\"]}]}]', '2026-09-01 10:28:50', '2026-09-02 08:20:41'),
