(897, 1240, 'analisa', '[{\"langkah\":\"Pengawas melakukan inspeksi area kerja\",\"bahaya\":[{\"risiko\":\"Pengawas tersandung dan terperosok di area beda tinggi\",\"pengendalian\":[\"Gunakan jalur yang rata saat memasuki area dumping point.\",\"Radius inspeksi 1 meter dari posisi beda tinggi.\"]},{\"risiko\":\"pengawas tertabrak unit yang sedang beroprasi di area disposal\",\"pengendalian\":[\"lakukan komununikasi 2 arah menggunakan channel disposal dengan unit yang berada di area disposal.\",\"gunakan jalur di luar radius 20 meter area manuver dan 10 meter jalur keluar masuk unit yang sedang beroprasi\"]}]},{\"langkah\":\"Dozer memasuki area dumping point\",\"bahaya\":[{\"risiko\":\"unit dozer tertabrak unit yang sedang beroprasi\",\"pengendalian\":[\"lakukan komunikasi 2 arah menggunakan channel disposal dengan pengawas dan unit yang sedang beroperasi di area disposal\",\"gunakan jalur muatan yang sudah terbentuk saat memasuki area dumping point\"]},{\"risiko\":\"unit dozer terperosok di area beda tinggi\",\"pengendalian\":[\"gunakan jalur yang rata yang sudah terbentuk saat memasuki area dumping point\",\"posisi  blade dozer rata dengan permukan jalur yang di lewati.\"]}]},{\"langkah\":\"dozer melakukan pembersihan dan perapian di area dumping point\",\"bahaya\":[{\"risiko\":\"unit dozer terperosok ke area beda tinggi\",\"pengendalian\":[\"saat melakukan dorongan material posisikan blade menekan ke bawa\",\"posisi dozer mendorong searah dengan arah dumpingan\",\"jalur pijakan track dozer di material yang keras.\"]}]},{\"langkah\":\"unit hauler memasuki area dumpingan\",\"bahaya\":[{\"risiko\":\"hauler tertabrak unit lain yang sedang beroprasi\",\"pengendalian\":[\"lakukan komunikasi 2 arah menggunakan channel disposal dengan unit lain yang sedang beroperasi\",\"gunakan jalur muatan saat memasuki area disposal\",\"manuver searah jarum jam\"]}]},{\"langkah\":\"Hauler mundur di area disposal untuk dumping material\",\"bahaya\":[{\"risiko\":\"unit hd terperosok di area beda tinggi\",\"pengendalian\":[\"gunakan limiter sebagai acuan batas dumping sejajar dengan kabin, denganjarak 16 meter dari posisi crest dumpingan sesuai rekomendasi dari team geotek\",\"jalur pijakan saat mundur di area yang sudah di layering dengan material bagus atau permukaan yang keras\",\"ikuti intruksi yang di berikan oleh pengawas atau dozer yang berada di area kerja disposal\",\"bunyikan klakson sebanyak 3x sebagai isyarat akan mundur di area dumpingan\"]},{\"risiko\":\"hauler tersenggol dengan unit yang sedang beroperasi\",\"pengendalian\":[\"lakukan komunikasi 2 arah menggunakan channel disposal dengan unit yang berada di area disposal\",\"gunakan isyarat klakson sebanyak 3 kali saat akan mundur di area disposal\"]}]},{\"langkah\":\"hauler mengankat dan menurunkan vessel di area disposal untuk membuang material\",\"bahaya\":[{\"risiko\":\"hauler terperosok di area disposal\",\"pengendalian\":[\"posisikan hauler saat akan dumping dalam posisi rata\",\"dudukan tyre hauler permukaan yang keras.\"]}]},{\"langkah\":\"hauler keluar dari area dumpingan\",\"bahaya\":[{\"risiko\":\"hauler tertabrak unit yang sedang beroperasi\",\"pengendalian\":[\"aktif komunikasi 2 arah menggunakan channel disposal dengan unit yang sedang beroperasi di area disposal\",\"gunakan jalur kosongan yang sudah di bentuk\"]},{\"risiko\":\"hauler terperosok di area beda tinggi\",\"pengendalian\":[\"saat keluar dari disposal gunakan jalur kosongan yang sudah di bentuk dan bersihkan dengan greader atau dozer.\"]}]},{\"langkah\":\"dozer mendorong tumpukan material poor bekas dumpingan hauler\",\"bahaya\":[{\"risiko\":\"dozer terperosok di area disposal\",\"pengendalian\":[\"dorong material poor ke ujung crest se arah dengan kemajuan disposal\",\"dorong tumpukan material poor perlahan sesuai kapasitas dorongan dozer\",\"posisi track di permukaan yang material keras\",\"dorong material poor ke ujung crest dumpingan sambil menekan blade untuk mendesak material poor melewati unung crest dumpingan.\",\"saat mundur gunakan jalur bekas dorongan material poor atau jalur yang permukaanya keras\",\"posisi dozer lurus searah dengan kemajuan dumpingan\"]}]},{\"langkah\":\"dozer mendorong material blendingan di area disposal\",\"bahaya\":[{\"risiko\":\"dozer terperosok di area disposal\",\"pengendalian\":[\"lakukan dorongan material blendingan ke area bekas dorongan material poor\",\"saat membagi material blendingan di area dumpingan posisi jalur track di area permukaan yang keras\",\"hampar material blendingan di area permukaan bekas dorongan material poor rata dengan area manuver hauler\"]}]},{\"langkah\":\"dozer keluar dari area dumpingan ke area parkiran\",\"bahaya\":[{\"risiko\":\"dozer tertabrak unit yang beroperasi\",\"pengendalian\":[\"lakukan komunikasi 2 arah menggunakan channel disposal\",\"ikuti jalur kosongan yang sudah di bentuk\"]},{\"risiko\":\"doser terperosok di area disposal\",\"pengendalian\":[\"jalur keluar disposal di area yang rata\",\"posisi blade saat travel rata dengan permukaan jalur yang di lewati\"]}]}]', '2026-09-01 12:54:16', '2026-09-01 15:31:31'),
