(912, 1244, 'catatan_revisi', '[{\"no_rev\":1,\"tanggal\":\"2023-08-26\",\"halaman\":\"1\",\"catatan\":\"Perubahan Template pada Prosedur & ukuran font\"},{\"no_rev\":2,\"tanggal\":\"2023-10-26\",\"halaman\":\"1-4\",\"catatan\":\"Perubahan Template pada Prosedur & ukuran font\"},{\"no_rev\":3,\"tanggal\":\"2024-04-03\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval pengesahan\"},{\"no_rev\":4,\"tanggal\":\"2024-10-23\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval  pengesahan\"},{\"no_rev\":5,\"tanggal\":\"2024-10-18\",\"halaman\":\"3\",\"catatan\":\"Penambahan referensi Sistem Management Terintegrasi PT. Putra Perkasa Abadi\"},{\"no_rev\":1,\"tanggal\":\"2025-12-01\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval  pengesahan\"},{\"no_rev\":2,\"tanggal\":\"2026-03-15\",\"halaman\":\"1-10\",\"catatan\":\"Perubahan nomor prosedur, Perubahan pada bagian lampiran terkait nomor formulir, Perubahan Judul Pada Prosedur dan Perubahan pada tugas dan tanggung jawab\"}]', '2026-09-05 10:05:28', '2026-09-05 10:05:28'),
