(914, 1245, 'tujuan', '[\"Menjamin proses pengajuan, pengaturan (setting), dan penggunaan channel radio berjalan tertib, terdokumentasi, serta sesuai dengan ketentuan yang berlaku di lingkungan kerja PT PPA jobsite PT Adaro Indonesia dan mitra kerja\",\"Memastikan telah dilakukan registrasi ID PTT dan security acces code plug pada masing-masing radio\",\"Memastikan data channel radio yang terkonfigurasi pada radio sesuai dengan kebutuhan di lapangan\"]', '2026-09-05 10:05:42', '2026-09-05 10:06:00'),
(915, 1245, 'ruang_lingkup', '[\"Prosedur ini berlaku untuk kebutuhan radio unit dan radio handy talky (HT) yang beroperasional di area PPA job site Adaro Indonesia\"]', '2026-09-05 10:05:42', '2026-09-05 10:06:07'),
(916, 1245, 'referensi', '[\"Peraturan Menteri Komunikasi dan Informatika Nomor 1 Tahun 2019 tentang Penggunaan Spektrum Frekuensi Radio Berdasarkan Izin Kelas.\",\"PPA-HO-MAN-COE-001 Manual Sistem Manajemen Terintegrasi\",\"ISO 27001:2022 klausul 8.9 tentang Configuration management\",\"Memorandom Ketaatan Penggunaan Radio Komunikasi dan Frekuensi Radio 114-AI-HRGA-MO-XI-2021\"]', '2026-09-05 10:05:42', '2026-09-05 10:06:40'),
(917, 1245, 'definisi', '[\"Channel Radio adalah Frekuensi komunikasi yang digunakan untuk operasional kerja\",\"BA Radio (Berita Acara Radio) adalah Dokumen resmi dari pihak Adaro sebagai dasar penggunaan channel\",\"ICT adalah Tim yang bertanggung jawab atas pengelolaan perangkat dan konfigurasi radio komunikasi\",\"Radio komunikasi adalah perangkat elektronik yang digunakan untuk mengirim dan menerima pesan suara melalui gelombang radio tanpa menggunakan kabel\",\"Codeplug adalah File konfigurasi radio\",\"PTT ID Adalah Identitas komunikasi radio\",\"Commissioning adalah Proses pengoperasian awal unit baru\",\"Re-Commissioning Adalah Pengaktifan kembali unit yang sebelumnya tidak beroperasi\"]', '2026-09-05 10:05:42', '2026-09-05 10:08:18'),
(918, 1245, 'pakai_flowchart', '\"1\"', '2026-09-05 10:09:51', '2026-09-05 10:09:51'),
(919, 1245, 'flowchart', '[{\"judul\":\"Flowchart Pengajuan Channel Radio oleh Mitra Kerja\",\"gambar\":\"lampiran\\/ICTMD\\/SOP\\/img_6a9b79f59b8cc.png\",\"keterangan\":\"-\"},{\"judul\":\"Flowchart Pengajuan Channel Radio oleh Departemen Plant\",\"gambar\":\"lampiran\\/ICTMD\\/SOP\\/img_6a9b7cf35e87e.png\",\"keterangan\":\"-\"},{\"judul\":\"Flowchat Pengajuan Channel Radio untuk unit transport\",\"gambar\":\"lampiran\\/ICTMD\\/SOP\\/img_6a9b7e87067c2.png\",\"keterangan\":\"-\"}]', '2026-09-05 10:09:51', '2026-09-05 10:29:34'),
(920, 1245, 'aktivitas', '[{\"sub_judul\":\"Pengajuan Channel Radio oleh Mitra Kerja\",\"deskripsi\":\"<p><strong>Pengajuan Permohonan Channel PPA oleh Mitra kerja PPA dan mitra kerja Adaro<\\/strong><\\/p><ul><li><strong>Kegiatan :<\\/strong><\\/li><li>User mitra kerja mengajukan permohonan penambahan channel radio PPA ke tim ICT.<\\/li><li>User wajib membawa radio fisik ke ICT beserta Berita Acara (BA) Radio menggunakan formulir Adaro.<\\/li><li>Mengisi Formulir Pengajuan Channel Radio PPA menggunakan formulir PPA.<\\/li><\\/ul>\",\"pic\":\"USER\"},{\"sub_judul\":\"Verifikasi & Analisa Kebutuhan\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Tim ICT melakukan konfirmasi kepada user terkait area kerja yang akan diakses di area operasional PPA.<\\/li><li>Berdasarkan hasil verifikasi, ICT menentukan channel radio yang sesuai dengan kebutuhan user.<\\/li><\\/ul>\",\"pic\":\"ICT\"},{\"sub_judul\":\"Konfigurasi Channel dan Approval\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Tim ICT melakukan setting \\/ konfigurasi channel radio pada perangkat radio user.<\\/li><li>Setelah konfigurasi selesai Group Leader ICT melakukan Approval pada Formulir Berita Acara (BA) Radio dari user serta penambahan stempel resmi PT PPA pada kolom approval<\\/li><\\/ul>\",\"pic\":\"ICT & GL ICT\"},{\"sub_judul\":\"Dokumentasi\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Tim ICT wajib melakukan dokumentasi dengan melakukan Foto copy BA yang telah dilakukan approval.<\\/li><li>Seluruh dokumen disimpan sebagai arsip resmi ICT.<\\/li><\\/ul>\",\"pic\":\"ICT\"},{\"sub_judul\":\"Ketentuan untuk User dengan Kewenangan Setting\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Bagi user\\/mitra kerja yang telah memiliki kewenangan setting channel tidak wajib membawa radio ke ICT.<\\/li><li>User tetap wajib membawa Formulir BA Radio menggunakan formulir Adaro serta mengisi Formulir Pengajuan Channel Radio PPA.<\\/li><li>Tim ICT melakukan verifikasi dokumen serta mendokumentasikan sebagai arsip resmi<\\/li><\\/ul>\",\"pic\":\"USER & ICT\"},{\"sub_judul\":\"Pengajuan Channel Radio oleh Departement Plant\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>User Departemen Plant mengajukan permintaan setting channel radio untuk Commissioning atau Re-Commissioning.<\\/li><li>User wajib melakukan konfirmasi kepada tim ICT minimal 2 (dua) minggu sebelum jadwal commissioning \\/ re-commissioning<\\/li><\\/ul>\",\"pic\":\"USER\"},{\"sub_judul\":\"Pengajuan setting channel untuk Persiapan Commissioning (Unit Baru)\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>User Departemen Plant wajib mengantarkan radio ke tim ICT untuk dilakukan seting channel serta menyampaikan nomor lambung unit yang akan menggunakan radio tersebut.<\\/li><li>Tim ICT akan melakukan konfirmasi area kerja yang akan diakses.<\\/li><li>ICT menentukan dan melakukan setting channel sesuai kebutuhan operasional.<\\/li><\\/ul>\",\"pic\":\"USER & ICT\"},{\"sub_judul\":\"Pengajuan setting channel radio untuk proses Re-Commissioning (Unit Existing)\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>User cukup menginformasikan nomor lambung unit kepada ICT.<\\/li><li>Tim ICT akan menjadwalkan pengambilan codeplug langsung ke unit.<\\/li><li>Melakukan penyesuaian konfigurasi channel sesuai kebutuhan.<\\/li><\\/ul>\",\"pic\":\"USER & ICT\"},{\"sub_judul\":\"Konfigurasi & Administrasi oleh ICT\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>ICT melakukan konfirmasi area operasional unit yang akan menggunakan radio tersebut.<\\/li><li>ICT melakukan Setting channel radio sesuai dengan kebutuhan.<\\/li><li>Tim ICT menyusun Berita Acara (BA) menggunakan formulir dari Adaro.<\\/li><\\/ul>\",\"pic\":\"ICT\"},{\"sub_judul\":\"Identifikasi & Penyerahan Unit Radio\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Setelah konfigurasi selesai, ICT melakukan pemasangan stiker pada radio sebagai identitas radio<\\/li><li>Mencantumkan nomor lambung unit, Type Radio dan ID PTT<\\/li><li>ICT melakukan registrasi data radio dengan data sebagai berikut :<\\/li><\\/ul><ol><li>Nomor lambung unit yang akan menggunakan radio tersebut.<\\/li><li>Jenis unit.<\\/li><li>Serial Number (S\\/N) Radio.<\\/li><li>Type radio.<\\/li><li>Merek radio.<\\/li><li>ID PTT<\\/li><li>Tanggal konfigurasi<\\/li><\\/ol><ul><li>Radio diserahkan kembali kepada user<\\/li><\\/ul>\",\"pic\":\"ICT\"},{\"sub_judul\":\"Tim ICT melakukan pengajuan approval melalui email kepada Tim GA Radio komunikasi AI\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><\\/ul><ol><li>Apabila Formulir Berita Acara (BA) telah selesai dibuat dan unit membutuhkan channel radio punya kontraktor lain maka ICT wajib mengajukan permohonman approval kepada Perusahaan pemilik channel radio tersebut.<\\/li><li>Apabila channel radio yang digunakan tidak membutuhkan channel kontraktor lain maka ICT cukup melakukan pengajuan approval kepada Tim IT GA Radio Adaro melalui email dengan melampirkan codeplug.<\\/li><li>Apabila formulir BA telah dilakukan approval oleh IT GA Radio Adaro maka ICT meneruskan dokumen Berita acara kepada Departemen Plant untuk keperluan commissioning atau Re-commissioning.<\\/li><\\/ol>\",\"pic\":\"ICT\"},{\"sub_judul\":\"Pengajuan Channel Radio Unit Transport\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>User mengajukan permintaan setting channel radio ke tim ICT<\\/li><li>User wajib membawa unit radio ke ICT serta mengisi Formulir Pengajuan Setting Channel PPA<\\/li><\\/ul>\",\"pic\":\"USER\"},{\"sub_judul\":\"Verifikasi & Konfigurasi oleh ICT\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Tim ICT melakukan Konfirmasi area kerja yang akan diakses oleh unit.<\\/li><li>Penentuan channel sesuai kebutuhan operasional.<\\/li><li>Tim ICT melakukan konfigurasi channel radio.<\\/li><li>ICT Pembuatan Berita Acara (BA) Radio menggunakan formulir dari Adaro<\\/li><\\/ul>\",\"pic\":\"ICT\"},{\"sub_judul\":\"Registrasi & Penyerahan Radio\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Setelah konfigurasi selesai, ICT melakukan pemasangan stiker identitas radio dan mencantumkan ID PTT yang telah diberikan.<\\/li><li>ICT melakukan Registrasi data radio (database ICT) antara lain :<\\/li><\\/ul><ol><li>Nomor lambung unit yang akan menggunakan radio tersebut.<\\/li><li>Jenis unit.<\\/li><li>Serial Number (S\\/N) Radio.<\\/li><li>Type radio.<\\/li><li>Merek radio.<\\/li><li>ID PTT<\\/li><li>Tanggal konfigurasi.<\\/li><\\/ol><ul><li>Radio diserahkan kembali kepada user<\\/li><\\/ul>\",\"pic\":\"ICT\"},{\"sub_judul\":\"Kewajiban Dokumentasi oleh User\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>  User wajib mengirimkan dokumentasi berikut kepada ICT:<\\/li><\\/ul><ol><li>Foto antena radio terpasang<\\/li><li>Foto radio terpasang di dalam kabin unit<\\/li><li>Foto instalasi kabel power radio<\\/li><li>Foto Serial Number radio<\\/li><\\/ol>\",\"pic\":\"USER\"},{\"sub_judul\":\"Uji Kelayakan & Administrasi Lanjutan\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><li>Berdasarkan dokumentasi yang diterima, ICT akan menyusun Berita Acara Uji Kelayakan Radio menggunakan formulir Adar.<\\/li><li>ICT melanjutkan proses pengajuan approval kepada perusahaan pemilik channel apabila ada channel Perusahaan lain yang akan digunakan.<\\/li><li>Apabila Formulir Berita Acara dan Checklist uji kelayakan sudah selesai dibuat maka tim ICT wajib mengajukan approval kepada IT GA Adaro melalui email.<\\/li><li>Apabila dokumen telah full approval maka ICT mengirimkan formular Berita Acara dan Checklist uji kelayakan radionya kepada user.<\\/li><\\/ul>\",\"pic\":\"ICT\"}]', '2026-09-05 10:09:51', '2026-09-05 10:51:12'),
(921, 1245, 'lampiran', '[{\"dokumen\":\"F-AI-GAF-00-01\",\"keterangan\":\"Formulir Kelayakan Radio\"},{\"dokumen\":\"F-AI-GAF-00-02\",\"keterangan\":\"Formulir checklist channel radio\"},{\"dokumen\":\"PPA-ADRO-F-ICTMD-011\",\"keterangan\":\"Formulir Pengajuan seting channel radio PPA\"},{\"dokumen\":\"PPA-ADRO-IK-ICTMD-028\",\"keterangan\":\"IK Konfigurasi channel radio komunikasi & ID PTT\"}]', '2026-09-05 10:09:51', '2026-09-05 10:30:36'),
(922, 1246, 'catatan_revisi', '[{\"no_rev\":1,\"tanggal\":\"2024-04-03\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval pengesahan\"},{\"no_rev\":2,\"tanggal\":\"2024-10-23\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval pengesahan\"},{\"no_rev\":3,\"tanggal\":\"2024-11-18\",\"halaman\":\"3\",\"catatan\":\"Penambahan referensi Sistem Management Terintegrasi PT. Putra Perkasa Abadi\"},{\"no_rev\":4,\"tanggal\":\"2024-11-30\",\"halaman\":\"3\",\"catatan\":\"Revisi Referensi Sistem Management Ter Integrasi PT. Putra Perkasa Abadi\"},{\"no_rev\":5,\"tanggal\":\"2025-12-01\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval  Pengesahan\"},{\"no_rev\":1,\"tanggal\":\"2026-03-15\",\"halaman\":\"1-7\",\"catatan\":\"Perubahan nomor prosedur, Perubahan pada bagian lampiran terkait nomor formulir, Perubahan judul pada prosedur dan Perubahan tugas dan tanggung jawab\"}]', '2026-09-05 13:23:27', '2026-09-05 13:23:27'),
(923, 1247, 'catatan_revisi', '[{\"no_rev\":1,\"tanggal\":\"2024-04-03\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval pengesahan\"},{\"no_rev\":2,\"tanggal\":\"2024-10-23\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval pengesahan\"},{\"no_rev\":3,\"tanggal\":\"2024-11-18\",\"halaman\":\"3\",\"catatan\":\"Penambahan referensi Sistem Management Terintegrasi PT. Putra Perkasa Abadi\"},{\"no_rev\":4,\"tanggal\":\"2024-11-30\",\"halaman\":\"3\",\"catatan\":\"Revisi Referensi Sistem Management Ter Integrasi PT. Putra Perkasa Abadi\"},{\"no_rev\":5,\"tanggal\":\"2025-12-01\",\"halaman\":\"1\",\"catatan\":\"Perubahan approval  Pengesahan\"},{\"no_rev\":1,\"tanggal\":\"2026-03-15\",\"halaman\":\"1-7\",\"catatan\":\"Perubahan nomor prosedur, Perubahan pada bagian lampiran terkait nomor formulir, Perubahan judul pada prosedur dan Perubahan tugas dan tanggung jawab\"}]', '2026-09-05 13:23:27', '2026-09-05 13:23:27'),
(924, 1247, 'tujuan', '[\"Untuk melakukan inspeksi teknis pada lokasi, perangkat dan media Tower atau Menara untuk memenuhi persyaratan standar teknis minimum PT Putra Perkasa Abadi\",\"Sebagai panduan proses Inspeksi Integrasi Menara SST & Combat\",\"Terlaksananya proses pemeliharan secara berkelanjutan untuk memastikan setandar keamanan infrastruktur Tower SST, Combat, & perangkat BTS yang dimiliki\"]', '2026-09-05 13:24:01', '2026-09-06 09:02:45'),
(925, 1247, 'ruang_lingkup', '[\"Prosedur ini berlaku untuk kegiatan yang diperlukan untuk menjamin persyaratan standar teknis minimum dan kondisi keselamatan lokasi Tower\\/Menara di area kerja PT Putra Perkasa Abadi job site PT Adaro Indonesia\",\"Dokumentasi proses bisnis ini mencakup kegiatan melakukan inspeksi menara oleh petugas yang ditunjuk dan dilakukan pengawasan\",\"Kegiatan inspeksi dilakukan sebagai pemenuhan data Engineering untuk menindaklanjuti ditemukannya permasalahan dari hasil pemeliharaan Preventif\\/Korektif, audit, dan komunitas\"]', '2026-09-05 13:24:01', '2026-09-06 09:03:00'),
(926, 1247, 'referensi', '[\"PP No.05 Tahun 2012 Tentang penerapan SMK3\",\"Kepmen ESDM No. 1827 Tahun 2018 Elemen IV.4.1. Sistem dan Pelaksanaan Pemeliharaan\\/ Perawatan Sarana, Prasarana, Instalasi & Peralatan\",\"Pembaharuan referensi KepDirjen No. 185.K\\/37.04\\/DJB\\/2019  Tentang Petunjuk Teknis Pelaksanaan Keselamatan Pertambangan dan Pelaksanaan, Penilaian, dan Pelaporan Sistem Manajemen Keselamatan Pertambangan dan Mineral\",\"ISO 9001:2015 Klausul 7.1.3 Infrastruktur\",\"ISO 14001:2015 Klausul 7.1.3 Sarana dan Prasarana\",\"ISO 45001:2018 Klausul 8.1 Perencanaan dan Pengendalian Operasional\",\"PPA-HO-MAN-COE-001 Manual Sistem Manajemen Terintegrasi\",\"ISO 27001:2022 Klausul 7.13 tentang Equipment maintenance\"]', '2026-09-05 13:24:01', '2026-09-06 09:03:30'),
(927, 1247, 'definisi', '[\"Tower SST (Self Supporting Tower) adalah jenis menara telekomunikasi yang dapat berdiri sendiri tanpa bantuan kawat penahan (guy wire). Tower ini memiliki struktur rangka baja segitiga atau segiempat yang kokoh dan biasanya digunakan untuk mendukung perangkat BTS\",\"Tower Mobile Combat adalah menara telekomunikasi portabel yang dirancang khusus untuk digunakan dalam kondisi darurat, militer, atau lokasi sulit dijangkau yang umumnya memiliki struktur yang berdiri dengan keamanan seling suai serta tidak menetap\",\"Inspeksi Tower merupakan kegiatan yang dilakukan untuk memastikan bahwa menara dan infrastruktur pendukung lainnya memenuhi persyaratan teknis minimum dalam kondisi aman, memenuhi aspek Mutu, Kesehatan, Keselamatan dan lingkungan\",\"Perangkat BTS (Base Transceiver Station) adalah perangkat infrastruktur penting dalam jaringan komunikasi seluler yang berfungsi untuk menghubungkan perangkat pengguna (HP\\/smartphone) dengan jaringan operator melalui sinyal radio yang terdiri dari beberapa perangkat server dan wireless.\",\"Mitra Kerja adalah individu, kelompok, organisasi, atau perusahaan yang bekerja sama dalam suatu kegiatan atau proyek dengan tujuan untuk mencapai hasil bersama berdasarkan kesepakatan tertentu. Perusahaan yang telah di tunjuk sebagai pelaksana pemeliharan di area kerja PT Puta Perkasa Abadi Job Site PT Adarao Indonesia antaralai sebagai berikut : PT Solusi Tunas Pratama (STP) bertanggung jawab atas proses Pembangunan dan pembongkaran Tower BTS dan Combat di area kerja PT PPA job site PT Adaro Indonesia, serta sebagi pihak yang melakukan evaluasi dari hasil pemeriksaan dan pemeliharaan Tower secara berkala, PT Biliton Jaya Raya sebagai pelaksana pemeliharaan rutin (bulanan) dan PT Telkom sebagai penanggung jawab terkait dengan perangkat BTS dan Jaringan Telkomsel pada Tower\"]', '2026-09-05 13:24:01', '2026-09-06 09:05:45'),
(928, 1248, 'catatan_revisi', '[{\"no_rev\":1,\"tanggal\":\"2023-09-01\",\"halaman\":\"1\",\"catatan\":\"Perubahan identifikasi dokumen salinan terkendali dan asli dari tanda centang ke stempel.\\r\\nPerubahan identifikasi dokumen Salinan tidak terkendali menjadi soft copy dan diberi stempel.\"},{\"no_rev\":2,\"tanggal\":\"2023-10-25\",\"halaman\":\"1\",\"catatan\":\"Perubahan cover dan format dan menyesuaikan format dari PPA Head Office\"},{\"no_rev\":3,\"tanggal\":\"2024-05-05\",\"halaman\":\"5-8\",\"catatan\":\"Perubahan Jenis Energi\\r\\nPenetapan Baseline & Jenis Indikator Kinerja Energi (Liter\\/bcm)\\r\\nPenentuan Metode yang digunakan\\r\\nDiagram Alir\"},{\"no_rev\":4,\"tanggal\":\"2024-10-22\",\"halaman\":\"1\",\"catatan\":\"Perubahan lembar pengesahan dokumen oleh personel yang berwenang\"},{\"no_rev\":5,\"tanggal\":\"2024-11-22\",\"halaman\":\"3\",\"catatan\":\"Penambahan Referensi SMT PT. Putra Perkasa Abadi\"},{\"no_rev\":1,\"tanggal\":\"2025-12-01\",\"halaman\":\"1\",\"catatan\":\"Revisi pada kolom approval persetujuan PJO\"},{\"no_rev\":2,\"tanggal\":\"2025-03-15\",\"halaman\":\"1-6\",\"catatan\":\"Perubahan nomor Prosedur dan Perubahan pada bagian lampiran terkait nomor formulir\"},{\"no_rev\":3,\"tanggal\":\"2026-08-01\",\"halaman\":\"1-3\",\"catatan\":\"Penambahan Diagram Alir dan Penambahan Referensi\"}]', '2026-09-06 08:36:23', '2026-09-06 08:36:23'),
(929, 1249, 'catatan_revisi', '[{\"no_rev\":1,\"tanggal\":\"2023-09-01\",\"halaman\":\"1\",\"catatan\":\"Perubahan identifikasi dokumen salinan terkendali dan asli dari tanda centang ke stempel.\\r\\nPerubahan identifikasi dokumen Salinan tidak terkendali menjadi soft copy dan diberi stempel.\"},{\"no_rev\":2,\"tanggal\":\"2023-10-25\",\"halaman\":\"1\",\"catatan\":\"Perubahan cover dan format dan menyesuaikan format dari PPA Head Office\"},{\"no_rev\":3,\"tanggal\":\"2024-05-05\",\"halaman\":\"5-8\",\"catatan\":\"Perubahan Jenis Energi\\r\\nPenetapan Baseline & Jenis Indikator Kinerja Energi (Liter\\/bcm)\\r\\nPenentuan Metode yang digunakan\\r\\nDiagram Alir\"},{\"no_rev\":4,\"tanggal\":\"2024-10-22\",\"halaman\":\"1\",\"catatan\":\"Perubahan lembar pengesahan dokumen oleh personel yang berwenang\"},{\"no_rev\":5,\"tanggal\":\"2024-11-22\",\"halaman\":\"3\",\"catatan\":\"Penambahan Referensi SMT PT. Putra Perkasa Abadi\"},{\"no_rev\":1,\"tanggal\":\"2025-12-01\",\"halaman\":\"1\",\"catatan\":\"Revisi pada kolom approval persetujuan PJO\"},{\"no_rev\":2,\"tanggal\":\"2025-03-15\",\"halaman\":\"1-6\",\"catatan\":\"Perubahan nomor Prosedur dan Perubahan pada bagian lampiran terkait nomor formulir\"},{\"no_rev\":3,\"tanggal\":\"2026-08-01\",\"halaman\":\"1-3\",\"catatan\":\"Penambahan Diagram Alir dan Penambahan Referensi\"}]', '2026-09-06 08:36:23', '2026-09-06 08:36:23'),
(930, 1249, 'tujuan', '[\"Prosedur ini disusun untuk memberikan panduan dalam melakukan proses pengelolaan energi dengan tujuan sebagai berikut : Melakukan tinjauan dan analisis kinerja energi secara komprehensif, Dapat menentukan pengguna energi signifikan yang tepat, Menentukan evaluasi atas ketidaksesuaian pengelolaan energy dan Dapat menentukan program yang sesuai sebagai tindakan dalam melakukan efisiensi energi.\"]', '2026-09-06 08:38:10', '2026-09-06 08:45:02'),
(931, 1249, 'ruang_lingkup', '[\"Prosedur ini melingkupi cara melakukan tinjauan energi yang berlaku untuk seluruh lokasi kegiatan operasional Perusahaan, dalam rangka penerapan sistem manajemen energi berdasarkan ISO 50001:2018\"]', '2026-09-06 08:38:10', '2026-09-06 08:38:10'),
(932, 1249, 'referensi', '[\"Undang-Undang Republik Indonesia Nomor 01 Tahun 1970 Tentang Keselamatan Kerja\",\"Undang-Undang Republik Indonesia Nomor 03 Tahun 2020 Tentang Pertambangan Mineral dan Batubara\",\"Undang-Undang Republik Indonesia Nomor 11 Tahun 2020 Tentang Cipta Kerja\",\"Peraturan Pemerintah Republik Indonesia Nomor 50 Tahun 2012 Tentang Penerapan Sistem Manajemen Keselamatan dan Kesehatan Kerja\",\"Peraturan Menteri Energi dan Sumber Daya Mineral Republik Indonesia Nomor 26 Tahun 2018 Tentang Pelaksanaan Kaidah Pertambangan yang baik dan pengawasan pertambangan Mineral dan Batubara\",\"Keputusan Menteri Energi dan Sumber Daya Mineral Republik Indonesia Nomor 1827 K\\/30\\/MEM\\/2018 Tentang Pedoman Pelaksanaan Kaidah Teknik Pertambangan yang Baik\",\"Keputusan Direktur Jendral Mineral dan Batubara Nomor 185.K\\/37.04\\/DJB\\/2019 Petunjuk teknis pelaksanaan keselamatan pertambangan dan pelaksanaan, penilaian, dan pelaporan sistem manajemen keselamatan pertambangan mineral dan Batubara\",\"ISO 9001:2015 Tentang Sistem Manajemen Mutu\",\"ISO 14001:2015 Tentang Sistem Manajemen Lingkungan\",\"ISO 45001:2018 Tentang Sistem Manajemen Keselamatan dan Kesehatan Kerja\",\"ISO 50001:2018 Tentang Sistem Manajemen Energi\",\"PPA-HO-MAN-COE-001 Manual K3PLM\",\"Kebijakan Sistem Management Terintegrasi PT. Putra Perkasa Abadi No. PPA-SMT- PD-001\",\"Kepmen ESDM No. 257.K\\/EK.01\\/MEM.E\\/2026\"]', '2026-09-06 08:38:10', '2026-09-06 08:43:20'),
(933, 1249, 'definisi', '[\"Energi adalah sumber daya yang digunakan untuk menghasilkan suatu produk atau jasa. Energi berupa energi listrik atau bahan bakar\",\"Kinerja Energi adalah hasil terukur terkait dengan efisiensi energi dan penggunaan energi. Kinerja Sistem Manajemen Energi adalah kesesuaian implementasi manajemen energi dengan kebijakan, tujuan, sasaran dan program serta Standar ISO 50001\",\"Baseline Energi adalah data acuan penggunaan energi sebagai pembanding dengan hasil capaian kinerja energi\",\"Indikator Kinerja Energi (IKE) adalah kriteria pencapaian penggunaan energi terhadap satuan keluaran produksi\",\"Pengguna Energi signifikan (PES)\\/Significant Energi User (SEU) adalah pengguna energi yang memiliki konsumsi energi yang besar dan\\/atau menawarkan potensi besar untuk peningkatan kinerja energi\"]', '2026-09-06 08:38:10', '2026-09-06 08:44:25'),
(934, 1249, 'pakai_flowchart', '\"1\"', '2026-09-06 08:45:43', '2026-09-06 08:45:43'),
(935, 1249, 'flowchart', '[{\"judul\":\"Flowchart Energi\",\"gambar\":\"lampiran\\/ICTMD\\/SOP\\/img_6a9cb7b66230c.png\",\"keterangan\":\"-\"}]', '2026-09-06 08:45:43', '2026-09-06 08:45:59');
INSERT INTO `document_contents` (`id`, `document_id`, `section_key`, `value_json`, `created_at`, `updated_at`) VALUES
(936, 1249, 'aktivitas', '[{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Identifikasi jenis energi yang digunakan oleh PT Putra Perkasa Abadi, dengan pertimbangan penggunaan energi yang dapat dikendalikan. Berdasarkan identifikasi awal, ruang lingkup dan batasan penggunaan energi di PT Putra Perkasa Abadi adalah sebagai berikut :<\\/p><ul><li>Jenis energi: Bio-solar<\\/li><li>Kegiatan : <em>Coal Mining (Overburden Removal, Coal Getting, Coal Hauling, Road Maintenance <\\/em>dan<em> Dewatering)<\\/em><\\/li><\\/ul>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Mengumpulkan data konsumsi energi sebagai bahan pertimbangan pembuatan baseline. Data konsumsi energi yang diperlukan adalah :<\\/p><ul><li>Konsumsi energi bulanan secara total<\\/li><li>Data produksi dan\\/atau output masing-masing proses kegiatan<\\/li><\\/ul>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Mengidentifikasi pengguna energi selama satu tahun terakhir, identifikasi yang dilakukan mencakup :<\\/p><ul><li>Pengguna energi yang dimaksud adalah seluruh sarana, prasarana, dan instalasi pertambangan (SPIP). <\\/li><li>Data konsumsi energi masing-masing pengguna energi.<\\/li><li>Menentukan pengguna energi signifikan (SEU) berdasarkan pertimbangan konsumsi energi terbesar (sekitar 80%)  atau memiliki peluang efisiensi terbesar).<\\/li><\\/ul>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Melakukan analisa pengguna energi signifikan, yang mencakup:<\\/p><ul><li>Mengidentifikasi variabel-variabel yang relevan dalam konsumsi energi<\\/li><li>Mengidentifikasi personil-personil yang mempengaruhi kinerja energi<\\/li><li>Mengidentifikasi peluang-peluang <em>improvement<\\/em> yang memungkinkan untuk efisiensi energi, mencakup kegiatan yang low cost, medium cost, ataupun high cost. Peluang energi bersifat low cost untuk diterapkan<\\/li><\\/ul>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Menetapkan baseline energi. <\\/p><p>Baseline energi dapat ditinjau kembali berdasarkan hasil tinjauan energi, jika baseline energi sebelumnya tidak relevan atau sudah tidak menggambarkan kinerja organisasi saat ini, maka dapat ditetapkan baseline energi baru. Baseline energi yang digunakan merupakan review terhadap 1 - 2 tahun dari periode sebelumnya.<\\/p><p>Baseline energi dapat diubah sesuai dengan analisa dan rekomendasi tim energi<\\/p>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Indikator kinerja energi yang digunakan adalah intensitas energi dibandingkan dengan total produksi (Liter\\/bcm)<\\/p>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Menetapkan target efisiensi energi yang dapat dicapai pada masing-masing SEU. Penetapan target harus mampu mendorong pencapaian target efisiensi energi total Perusahaan.<\\/p><p>Metode yang digunakan untuk monitoring  adalah Rasio Produksi. Perbandingan Kinerja energi saat ini dengan Baseline. Sedangkan <em>Regression <\\/em>untuk melihat kesesuaian variabel data yang digunakan.<\\/p>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Membuat proyeksi konsumsi energi masing-masing SEU di masa mendatang. Proyeksi konsumsi energi masa mendatang mencakup tanpa atau dengan tindakan untuk mencapai efisiensi energi<\\/p>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Aktivitas tinjauan (Perencanaan klausul 6.1- 6.8) energi dilakukan peninjauan ulang dan diperbaharui jika diperlukan, minimal 1 tahun sekali atau jika ada perubahan signifikan dalam kegiatan operasional (Penambahan Produksi atau Penambahan Alat operasional)<\\/p>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Membuat rencana pengumpulan data energi, mencakup:<\\/p><ol><li>Variabel yang relevan dengan SEU<\\/li><li>Konsumsi energi total dan SEU<\\/li><li>Kriteria operasional SEU<\\/li><li>Faktor statis, jika ada<\\/li><\\/ol><p>Data yang relevan dengan rencana aksi untuk efisiensi energi<\\/p>\",\"pic\":\"Tim Manajemen Energi\"},{\"sub_judul\":\"-\",\"deskripsi\":\"<p>Melakukan pemantauan konsumsi energi secara harian dan bulanan serta pencapaian target efisiensi energi dibandingkan baseline<\\/p>\",\"pic\":\"Tim Manajemen Energi\"}]', '2026-09-06 08:45:43', '2026-09-06 09:00:49'),
(937, 1249, 'lampiran', '[{\"dokumen\":\"PPA-ADRO-F-ICTMD-021\",\"keterangan\":\"Formulir Energy Review Tools\"},{\"dokumen\":\"PPA-ADRO-IK-ICTMD-013\",\"keterangan\":\"IK Pengelolaan Data Kinerja Energi\"}]', '2026-09-06 08:45:43', '2026-09-06 08:59:38'),
(938, 1247, 'pakai_flowchart', '\"1\"', '2026-09-06 09:01:32', '2026-09-06 09:01:32'),
(939, 1247, 'flowchart', '[{\"judul\":\"Flowchart Aktivitas\",\"gambar\":\"lampiran\\/ICTMD\\/SOP\\/img_6a9cbc9629041.png\",\"keterangan\":\"-\"}]', '2026-09-06 09:01:32', '2026-09-06 09:06:33'),
(940, 1247, 'aktivitas', '[{\"sub_judul\":\"Perencanaan dan Penjadwalan\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><\\/ul><ol><li>Group Leader ICT bersama tim pelaksana menyusun jadwal pemeliharaan bulanan.<\\/li><li>Jadwal disusun dengan mempertimbangkan kondisi operasional dan tingkat risiko.<\\/li><li>Jadwal disampaikan kepada seluruh pihak terkait sebelum pelaksanaan.<\\/li><\\/ol>\",\"pic\":\"GL ICT & Pelaksana\"},{\"sub_judul\":\"Persiapan Administrasi dan Perizinan\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><\\/ul><ol><li>Group Leader ICT membuat Izin Kerja Khusus (IKK) apabila ada pekerjaan di ketinggian.<\\/li><li>Memastikan seluruh tenaga kerja dari PT Biliton Jaya Raya telah memiliki Mine Permit Adaro yang valid dan masih aktif.<\\/li><li>Melakukan safety briefing sebelum pekerjaan dimulai<strong>.<\\/strong><\\/li><\\/ol>\",\"pic\":\"GL ICT\"},{\"sub_judul\":\"Pelaksanaan Pemeliharaan\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><\\/ul><ol><li>Pemeliharaan dilakukan oleh tim dari PT Biliton Jaya Raya sesuai jadwal yang telah ditentukan.<\\/li><li>Kegiatan meliputi pemeriksaan struktur tower, perangkat pendukung, serta sistem pengamanan.<\\/li><li>Group Leader ICT melakukan pengawalan dan pengawasan secara melekat selama proses pekerjaan berlangsung<\\/li><\\/ol>\",\"pic\":\"GL ICT & Pelaksana\"},{\"sub_judul\":\"Dokumentasi dan Pelaporan\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><\\/ul><ol><li>Setelah pekerjaan selesai, mitra kerja wajib menyusun laporan hasil pemeliharaan.<\\/li><li>Bukti hasil pemeliharaan (laporan, foto, checklist) dikirimkan maksimal 2 (dua) minggu setelah pekerjaan selesai<\\/li><\\/ol>\",\"pic\":\"Pelaksana\"},{\"sub_judul\":\"Tindak Lanjut Temuan\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><\\/ul><ol><li>Apabila ditemukan ketidaksesuaian atau potensi bahaya pada tower:<\\/li><li>Mitra kerja wajib melakukan koordinasi dengan pihak terkait.<\\/li><li>Dilakukan tindakan perbaikan sesuai standar yang berlaku.<\\/li><li>Tower dinyatakan aman setelah dilakukan verifikasi dan perbaikan yang diperlukan.<\\/li><li>Apabila terdapat Gangguan terkait dengan jaringan Telkomsel maka Group Leader ICT wajib melaporkan kepada PT Telkom untuk dilakukan pengecekan<\\/li><\\/ol>\",\"pic\":\"GL ICT & Pelaksana\"},{\"sub_judul\":\"Tanggung Jawab Pihak Terkait\",\"deskripsi\":\"<ul><li><strong>Kegiatan :<\\/strong><\\/li><\\/ul><ol><li>PT Solusi Tunas Pratama bertanggung jawab terhadap Proses pembangunan Tower serta Pembongkaran tower.<\\/li><li>PT Biliton Jaya Raya bertanggung jawab terhadap pelaksanaan pemeliharaan rutin Pelaporan hasil pekerjaan serta tindak lanjut temuan di lapangan.<\\/li><li>PT Telkom bertanggung jawab atas ketersediaan jaringan internet public di area yang telah ditentukan serta pelaksana tindak lanjut temuan gangguan jaringan.<\\/li><li>Departemen ICTMD bertanggung jawab terhadap perencanaan dan pengendalian kegiatan, pengawasan pelaksanaan serta validasi hasil pemeliharaan<\\/li><\\/ol>\",\"pic\":\"GL ICT & Pelaksana\"}]', '2026-09-06 09:01:32', '2026-09-06 10:11:55'),
(941, 1247, 'lampiran', '[{\"dokumen\":\"F-OPR-001\",\"keterangan\":\"Formulir Preventive Maintenance Mechanical Electrical\"},{\"dokumen\":\"PPA-ADRO-F-ICTMD-029\",\"keterangan\":\"Formulir checklist rekap jadwal inspeksi\"},{\"dokumen\":\"PPA-ADRO-IK-ICTMD-033\",\"keterangan\":\"IK Pemeliharaan Tower Combat dan SST\"}]', '2026-09-06 09:01:32', '2026-09-06 09:07:21');
