(1, 'SOP', 'Standard Operating Procedure', '{\"doc_type\":\"SOP\",\"doc_type_label\":\"STANDARD OPERATING PROCEDURE\",\"header\":\"_kop\",\"footer\":\"_footer\",\"footer_text\":\"Dokumen elektronik ini merupakan dokumen tidak terkendali apabila dicetak.\",\"cover_page\":\"_cover\",\"steps\":[{\"step\":1,\"title\":\"Tujuan, Ruang Lingkup, Referensi & Definisi\",\"sections\":[{\"label\":\"I. TUJUAN\",\"auto_number\":\"1.\",\"key\":\"tujuan\",\"nama\":\"TUJUAN\",\"type\":\"rich_list\",\"min_items\":1,\"placeholder\":\"Masukkan poin tujuan...\"},{\"label\":\"II. RUANG LINGKUP\",\"auto_number\":\"2.\",\"key\":\"ruang_lingkup\",\"nama\":\"RUANG LINGKUP\",\"type\":\"rich_list\",\"min_items\":1,\"placeholder\":\"Masukkan poin ruang lingkup...\"},{\"label\":\"III. REFERENSI\",\"auto_number\":\"3.\",\"key\":\"referensi\",\"nama\":\"REFERENSI\",\"type\":\"reference_picker\",\"allow_add\":true,\"placeholder\":\"Masukkan referensi...\",\"suggestions\":[\"ISO 9001:2015 Sistem Manajemen Mutu\",\"ISO 45001:2018 Sistem Manajemen K3\",\"ISO 14001:2015 Sistem Manajemen Lingkungan\",\"SMKP Minerba (Permen ESDM No. 26\\/2018)\",\"UU No. 1 Tahun 1970 tentang Keselamatan Kerja\"]},{\"label\":\"IV. DEFINISI\",\"auto_number\":\"4.\",\"key\":\"definisi\",\"nama\":\"DEFINISI\",\"type\":\"rich_list\",\"placeholder\":\"Masukkan definisi...\"}]},{\"step\":2,\"title\":\"Flowchart, Aktivitas, Lampiran & Verifikasi\",\"title_tanpa_opsional\":\"Aktivitas, Lampiran & Verifikasi\",\"sections\":[{\"label\":\"V. FLOWCHART\",\"auto_number\":\"5.\",\"key\":\"flowchart\",\"nama\":\"FLOWCHART\",\"type\":\"repeatable_group\",\"bab_opsional\":true,\"toggle_key\":\"pakai_flowchart\",\"toggle_label\":\"Gunakan Flowchart\",\"min_groups\":1,\"page_break\":\"both\",\"required\":false,\"warn_if_empty\":true,\"add_button_label\":\"+ Tambah Flowchart\",\"group_fields\":[{\"key\":\"judul\",\"label\":\"Judul Flowchart\",\"type\":\"text\",\"placeholder\":\"Judul (Contoh: Alur Serah Terima Shift)\",\"warn_if_empty\":true},{\"key\":\"gambar\",\"label\":\"Gambar Flowchart\",\"type\":\"image\",\"image_accept\":\"image\\/jpeg,image\\/png\",\"image_max_mb\":2},{\"key\":\"keterangan\",\"label\":\"Keterangan\",\"type\":\"textarea\",\"placeholder\":\"Keterangan flowchart...\",\"warn_if_empty\":true}]},{\"label\":\"VI. AKTIVITAS DAN TANGGUNG JAWAB\",\"auto_number\":\"6.\",\"key\":\"aktivitas\",\"nama\":\"AKTIVITAS DAN TANGGUNG JAWAB\",\"type\":\"repeatable_group\",\"min_groups\":1,\"add_button_label\":\"+ Tambah Aktivitas\\/Tanggung Jawab\",\"group_fields\":[{\"key\":\"sub_judul\",\"label\":\"Sub Judul\",\"type\":\"text\",\"placeholder\":\"Sub Judul (Contoh: Tahap Persiapan)\"},{\"key\":\"deskripsi\",\"label\":\"Deskripsi Aktivitas\",\"type\":\"rich_text\",\"placeholder\":\"Uraikan langkahnya. Bisa ditebalkan, dibuat daftar bernomor, dikutip, atau disisipi foto.\"},{\"key\":\"pic\",\"label\":\"PIC\",\"type\":\"text\",\"placeholder\":\"PIC (Contoh: Tim ICT)\"}]},{\"label\":\"VII. LAMPIRAN\",\"auto_number\":\"7.\",\"key\":\"lampiran\",\"nama\":\"LAMPIRAN\",\"type\":\"repeatable_group\",\"min_groups\":1,\"add_button_label\":\"+ Tambah Lampiran\",\"required\":false,\"warn_if_empty\":true,\"group_fields\":[{\"key\":\"dokumen\",\"label\":\"Dokumen\",\"type\":\"document_picker\",\"placeholder\":\"Pilih dokumen Berlaku, atau ketik manual...\",\"warn_if_empty\":true},{\"key\":\"keterangan\",\"label\":\"Keterangan (opsional)\",\"type\":\"textarea\",\"placeholder\":\"Boleh dikosongkan.\",\"warn_if_empty\":true}]},{\"key\":\"pembuat_tambahan\",\"label\":\"Pembuat Tambahan (opsional)\",\"type\":\"user_picker\",\"multiple\":true,\"required\":false,\"hint\":\"Gunakan tombol + jika pembuat lebih dari 1 orang.\"},{\"key\":\"peninjau\",\"label\":\"Ditinjau Oleh (DH\\/SH)\",\"type\":\"user_picker\",\"role_filter\":[\"group_leader\",\"section_head\"],\"required\":true},{\"key\":\"penyetuju\",\"label\":\"Disetujui Oleh\",\"type\":\"user_picker\",\"role_filter\":[\"pimpinan\"],\"required\":true}]}],\"approval_page_layout\":{\"columns\":[\"Nama\",\"Jabatan\",\"Tanggal\",\"Pengesahan\"],\"rows\":[{\"role_label\":\"Dibuat Oleh\",\"role\":\"pembuat\"},{\"role_label\":\"Ditinjau Oleh\",\"role\":\"peninjau\"},{\"role_label\":\"Disetujui Oleh\",\"role\":\"penyetuju\"}],\"stamp_on_published\":\"APPROVED\"}}', 'inti', 'all_departments', 1, '2026-07-11 16:37:14', '2026-08-27 08:41:34'),
(2, 'IK', 'Instruksi Kerja', '{\"doc_type\":\"IK\",\"doc_type_label\":\"INSTRUKSI KERJA\",\"header\":\"_kop\",\"footer\":\"_footer\",\"footer_text\":\"Dokumen elektronik ini merupakan dokumen tidak terkendali apabila dicetak.\",\"cover_page\":\"_cover\",\"steps\":[{\"step\":1,\"title\":\"Aktivitas & Pengesahan\",\"sections\":[{\"key\":\"aktivitas\",\"label\":\"I. AKTIVITAS DAN TANGGUNG JAWAB\",\"type\":\"repeatable_group\",\"auto_number\":\"1.\",\"min_groups\":1,\"add_button_label\":\"+ Tambah Aktivitas\\/Tanggung Jawab\",\"group_fields\":[{\"key\":\"sub_judul\",\"label\":\"Sub Judul\",\"type\":\"text\",\"placeholder\":\"Sub Judul (Contoh: Pemeliharaan bulanan)\"},{\"key\":\"deskripsi\",\"label\":\"Deskripsi Aktivitas\",\"type\":\"rich_text\",\"placeholder\":\"Uraikan langkahnya. Bisa ditebalkan, dibuat daftar bernomor, dikutip, atau disisipi foto.\"},{\"key\":\"pic\",\"label\":\"PIC\",\"type\":\"text\",\"placeholder\":\"PIC (Contoh: ICT)\"}]},{\"key\":\"pembuat_tambahan\",\"label\":\"Pembuat Tambahan (opsional)\",\"type\":\"user_picker\",\"multiple\":true,\"required\":false,\"hint\":\"Gunakan tombol + jika pembuat lebih dari 1 orang.\"},{\"key\":\"peninjau_penyetuju\",\"label\":\"Ditinjau & Disetujui Oleh (SH\\/DH Dept)\",\"type\":\"user_picker\",\"role_filter\":[\"section_head\",\"departemen_head\"],\"required\":true}]}],\"approval_page_layout\":{\"columns\":[\"Nama\",\"Jabatan\",\"Tanggal\",\"Pengesahan\"],\"rows\":[{\"role_label\":\"Dibuat Oleh\",\"role\":\"pembuat\"},{\"role_label\":\"Ditinjau dan Disetujui Oleh\",\"role\":\"peninjau_penyetuju\"}],\"stamp_on_published\":\"APPROVED\"}}', 'inti', 'all_departments', 1, '2026-07-11 22:36:16', '2026-08-27 01:24:56'),
(3, 'SP', 'Standar Parameter', '{\"doc_type\":\"SP\",\"doc_type_label\":\"STANDAR PARAMETER\",\"header\":\"_kop\",\"footer\":\"_footer\",\"footer_text\":\"Dokumen elektronik ini merupakan dokumen tidak terkendali apabila dicetak.\",\"cover_page\":\"_cover\",\"steps\":[{\"step\":1,\"title\":\"Tujuan, Ruang Lingkup, Referensi & Definisi\",\"sections\":[{\"label\":\"I. TUJUAN\",\"auto_number\":\"1.\",\"key\":\"tujuan\",\"nama\":\"TUJUAN\",\"type\":\"rich_list\",\"min_items\":1,\"placeholder\":\"Masukkan poin tujuan...\"},{\"label\":\"II. RUANG LINGKUP\",\"auto_number\":\"2.\",\"key\":\"ruang_lingkup\",\"nama\":\"RUANG LINGKUP\",\"type\":\"rich_list\",\"min_items\":1,\"placeholder\":\"Masukkan poin ruang lingkup...\"},{\"label\":\"III. REFERENSI\",\"auto_number\":\"3.\",\"key\":\"referensi\",\"nama\":\"REFERENSI\",\"type\":\"reference_picker\",\"allow_add\":true,\"placeholder\":\"Masukkan referensi...\",\"suggestions\":[\"ISO 9001:2015 Sistem Manajemen Mutu\",\"ISO 45001:2018 Sistem Manajemen K3\",\"ISO 14001:2015 Sistem Manajemen Lingkungan\",\"SMKP Minerba (Permen ESDM No. 26\\/2018)\",\"UU No. 1 Tahun 1970 tentang Keselamatan Kerja\"]},{\"label\":\"IV. DEFINISI\",\"auto_number\":\"4.\",\"key\":\"definisi\",\"nama\":\"DEFINISI\",\"type\":\"rich_list\",\"placeholder\":\"Masukkan definisi...\"}]},{\"step\":2,\"title\":\"Aktivitas, Lampiran & Verifikasi\",\"sections\":[{\"label\":\"V. AKTIVITAS DAN TANGGUNG JAWAB\",\"auto_number\":\"5.\",\"key\":\"aktivitas\",\"nama\":\"AKTIVITAS DAN TANGGUNG JAWAB\",\"type\":\"repeatable_group\",\"min_groups\":1,\"add_button_label\":\"+ Tambah Aktivitas\\/Tanggung Jawab\",\"group_fields\":[{\"key\":\"sub_judul\",\"label\":\"Sub Judul\",\"type\":\"text\",\"placeholder\":\"Sub Judul (Contoh: Tahap Persiapan)\"},{\"key\":\"deskripsi\",\"label\":\"Deskripsi Aktivitas\",\"type\":\"rich_text\",\"placeholder\":\"Uraikan langkahnya. Bisa ditebalkan, dibuat daftar bernomor, dikutip, atau disisipi foto.\"},{\"key\":\"pic\",\"label\":\"PIC\",\"type\":\"text\",\"placeholder\":\"PIC (Contoh: Tim ICT)\"}]},{\"label\":\"VI. LAMPIRAN\",\"auto_number\":\"6.\",\"key\":\"lampiran\",\"nama\":\"LAMPIRAN\",\"type\":\"repeatable_group\",\"min_groups\":0,\"add_button_label\":\"+ Tambah Lampiran Baru\",\"required\":false,\"group_fields\":[{\"key\":\"judul\",\"label\":\"Judul Lampiran\",\"type\":\"text\",\"placeholder\":\"Judul Lampiran (Contoh: Form Ceklis)\"},{\"key\":\"keterangan\",\"label\":\"Keterangan\",\"type\":\"textarea\",\"placeholder\":\"Keterangan \\/ caption lampiran (opsional)...\",\"warn_if_empty\":true},{\"key\":\"gambar\",\"label\":\"Foto \\/ Gambar (opsional)\",\"type\":\"image\",\"image_accept\":\"image\\/jpeg,image\\/png\",\"image_max_mb\":2}]},{\"key\":\"pembuat_tambahan\",\"label\":\"Pembuat Tambahan (opsional)\",\"type\":\"user_picker\",\"multiple\":true,\"required\":false,\"hint\":\"Gunakan tombol + jika pembuat lebih dari 1 orang.\"},{\"key\":\"peninjau_penyetuju\",\"label\":\"Ditinjau & Disetujui Oleh (SH\\/DH Dept)\",\"type\":\"user_picker\",\"role_filter\":[\"section_head\",\"departemen_head\"],\"required\":true}]}],\"approval_page_layout\":{\"columns\":[\"Nama\",\"Jabatan\",\"Tanggal\",\"Pengesahan\"],\"rows\":[{\"role_label\":\"Dibuat Oleh\",\"role\":\"pembuat\"},{\"role_label\":\"Ditinjau dan Disetujui Oleh\",\"role\":\"peninjau_penyetuju\"}],\"stamp_on_published\":\"APPROVED\"}}', 'inti', 'all_departments', 1, '2026-07-11 22:36:16', '2026-08-27 08:41:34'),
(4, 'JSA', 'Job Safety Analysis', '{\"doc_type\":\"JSA\",\"doc_type_label\":\"FORMULIR JOB SAFETY ANALYSIS\",\"orientation\":\"landscape\",\"header\":\"_kop_jsa\",\"footer\":\"_footer\",\"print_view\":\"documents.print.render-jsa\",\"footer_text\":\"Dokumen elektronik ini merupakan dokumen tidak terkendali apabila dicetak.\",\"approval_page\":\"_pengesahan\",\"steps\":[{\"step\":1,\"title\":\"Informasi Umum\",\"sections\":[{\"key\":\"lokasi_kerja\",\"label\":\"Lokasi Kerja\",\"type\":\"text\",\"placeholder\":\"mis. View Point\"},{\"key\":\"apd\",\"label\":\"APD yang digunakan\",\"type\":\"rich_list\",\"min_items\":1,\"placeholder\":\"mis. Helm safety, Body harness, Sarung tangan...\"},{\"key\":\"tools\",\"label\":\"Peralatan yang digunakan\",\"type\":\"rich_list\",\"min_items\":1,\"placeholder\":\"mis. Obeng, Bor, Tang...\"},{\"key\":\"form_tgl_efektif\",\"label\":\"Tgl. Efektif (kop)\",\"type\":\"date\"},{\"key\":\"peninjau\",\"label\":\"Ditinjau Oleh\",\"type\":\"user_picker\",\"role_filter\":[\"group_leader\",\"section_head\"],\"required\":true},{\"key\":\"penyetuju\",\"label\":\"Disetujui Oleh\",\"type\":\"user_picker\",\"role_filter\":[\"pimpinan\"],\"required\":true}]},{\"step\":2,\"title\":\"Analisa Bahaya\",\"sections\":[{\"key\":\"analisa\",\"label\":\"Analisa Bahaya\",\"type\":\"jsa_analysis\",\"help\":\"Masukkan tahapan pekerjaan, potensi bahaya yang mungkin timbul, dan langkah pengendaliannya.\"}]}],\"approval_page_layout\":{\"columns\":[\"Nama\",\"Jabatan\",\"Tanggal\",\"Pengesahan\"],\"rows\":[{\"role_label\":\"Dibuat Oleh\",\"role\":\"pembuat\"},{\"role_label\":\"Ditinjau Oleh\",\"role\":\"peninjau\"},{\"role_label\":\"Disetujui Oleh\",\"role\":\"penyetuju\"}],\"stamp_on_published\":\"APPROVED\"}}', 'inti', 'all_departments', 1, '2026-07-11 22:36:16', '2026-08-03 15:27:04'),
